SELECT id, provider, provider_id, users_id
FROM social_accounts
WHERE provider = #{provider}
  AND provider_id = #{provider_id}

SELECT id, provider, provider_id, users_id
FROM social_accounts
WHERE users_id = #{users_id}

SELECT id, email, nickname, status, role
FROM users
WHERE email = #{email}

SELECT id, email, nickname, status, role
FROM users
WHERE id = #{id}
